//! Хеш-функции и работа с hex-представлением.
//!
//! Коды типов совместимы с hashcat: 0=MD5, 100=SHA1, 1400=SHA256, 1700=SHA512.

use md5::Md5;
use sha1::Sha1;
use sha2::{Digest, Sha256, Sha512};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HashType {
    Md5,
    Sha1,
    Sha256,
    Sha512,
    Yescrypt,
}

impl HashType {
    /// Код hashcat.
    pub fn code(self) -> u32 {
        match self {
            HashType::Md5 => 0,
            HashType::Sha1 => 100,
            HashType::Sha256 => 1400,
            HashType::Sha512 => 1700,
            HashType::Yescrypt => 36100,
        }
    }

    pub fn name(self) -> &'static str {
        match self {
            HashType::Md5 => "MD5",
            HashType::Sha1 => "SHA1",
            HashType::Sha256 => "SHA256",
            HashType::Sha512 => "SHA512",
            HashType::Yescrypt => "Yescrypt",
        }
    }

    pub fn from_code(code: u32) -> Result<Self, String> {
        match code {
            0 => Ok(HashType::Md5),
            100 => Ok(HashType::Sha1),
            1400 => Ok(HashType::Sha256),
            1700 => Ok(HashType::Sha512),
            36100 => Ok(HashType::Yescrypt),
            other => Err(format!(
                "неподдерживаемый тип хеша -m {} (доступно: 0=MD5, 100=SHA1, 1400=SHA256, 1700=SHA512)",
                other
            )),
        }
    }
}

/// Хешировать байты, вернуть дайджест.
pub fn hash_bytes(ht: HashType, data: &[u8]) -> Vec<u8> {
    match ht {
        HashType::Md5 => {
            let mut h = Md5::new();
            h.update(data);
            h.finalize().to_vec()
        }
        HashType::Sha1 => {
            let mut h = Sha1::new();
            h.update(data);
            h.finalize().to_vec()
        }
        HashType::Sha256 => {
            let mut h = Sha256::new();
            h.update(data);
            h.finalize().to_vec()
        }
        HashType::Sha512 => {
            let mut h = Sha512::new();
            h.update(data);
            h.finalize().to_vec()
        }
        // Для Yescrypt не используется (цели — полные строки $y$, а не hex-дайджесты).
        HashType::Yescrypt => Vec::new(),
    }
}

/// Дайджест как hex-строка.
pub fn hash_hex(ht: HashType, data: &[u8]) -> String {
    hash_bytes(ht, data)
        .iter()
        .map(|b| format!("{:02x}", b))
        .collect()
}

/// Декодировать hex-строку в байты. Принимает как нижний, так и верхний регистр.
pub fn hex_decode(s: &str) -> Result<Vec<u8>, String> {
    let t = s.trim();
    if t.len() % 2 != 0 {
        return Err(format!("hex-строка '{}' имеет нечётную длину", s));
    }
    if t.is_empty() {
        return Err("пустая hex-строка".to_string());
    }
    let mut out = Vec::with_capacity(t.len() / 2);
    let bytes = t.as_bytes();
    for chunk in bytes.chunks_exact(2) {
        let hi = (chunk[0] as char).to_digit(16);
        let lo = (chunk[1] as char).to_digit(16);
        match (hi, lo) {
            (Some(h), Some(l)) => out.push((h * 16 + l) as u8),
            _ => return Err(format!("hex-строка '{}' содержит недопустимые символы", s)),
        }
    }
    Ok(out)
}

/// Проверка: известные тестовые векторы.
pub fn self_test() -> Result<(), String> {
    let cases: &[(HashType, &str, &str)] = &[
        (
            HashType::Md5,
            "abc",
            "900150983cd24fb0d6963f7d28e17f72",
        ),
        (
            HashType::Md5,
            "",
            "d41d8cd98f00b204e9800998ecf8427e",
        ),
        (
            HashType::Sha1,
            "abc",
            "a9993e364706816aba3e25717850c26c9cd0d89d",
        ),
        (
            HashType::Sha256,
            "abc",
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
        ),
        (
            HashType::Sha256,
            "",
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
        ),
        (
            HashType::Sha512,
            "abc",
            "ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2\
192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f",
        ),
