    // Yescrypt: проверка через libxcrypt crypt_r (полные строки $y$).
    const YESCRYPT_SETTING: &str =
        "$y$j9T$AtLRw25pW7qesridErMzD/$K16EoZmUeLGghIkhOpOvV.C/BCvFXEvtZuFVLoGcqe2";
    if !crate::yescrypt::yescrypt_verify(
        b"testpassword123",
