    if crate::yescrypt::yescrypt_verify(
        b"wrong",
        YESCRYPT_SETTING,
        &mut crate::yescrypt::CryptData::new(),
    ) {
        return Err("yescrypt self-test не пройден: неверный пароль подтверждён".to_string());
    }
    Ok(())
}

