// WGSL: GPU-брутфорс SHA256 по маске.

struct Params {
    batch_start: u64,
    batch_len: u32,
    mask_len: u32,
    num_targets: u32,
    digest_words: u32, // 8
};

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> charset: array<u32>;
@group(0) @binding(2) var<storage, read> charset_lens: array<u32>;
@group(0) @binding(3) var<storage, read> charset_starts: array<u32>;
@group(0) @binding(4) var<storage, read> targets: array<u32>;
@group(0) @binding(5) var<storage, read_write> results: array<atomic<u32>>; // [0]=счётчик пар, [1+2i]=lo, [2+2i]=hi

const RESULTS_CAPACITY: u32 = 1048576u; // пар (lo, hi)

const K: array<u32, 64> = array<u32, 64>(
    0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u,
    0x3956c25bu, 0x59f111f1u, 0x923f82a4u, 0xab1c5ed5u,
    0xd807aa98u, 0x12835b01u, 0x243185beu, 0x550c7dc3u,
    0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u, 0xc19bf174u,
    0xe49b69c1u, 0xefbe4786u, 0x0fc19dc6u, 0x240ca1ccu,
    0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau,
    0x983e5152u, 0xa831c66du, 0xb00327c8u, 0xbf597fc7u,
    0xc6e00bf3u, 0xd5a79147u, 0x06ca6351u, 0x14292967u,
    0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu, 0x53380d13u,
    0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u,
    0xa2bfe8a1u, 0xa81a664bu, 0xc24b8b70u, 0xc76c51a3u,
    0xd192e819u, 0xd6990624u, 0xf40e3585u, 0x106aa070u,
    0x19a4c116u, 0x1e376c08u, 0x2748774cu, 0x34b0bcb5u,
    0x391c0cb3u, 0x4ed8aa4au, 0x5b9cca4fu, 0x682e6ff3u,
    0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
    0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u
);

fn rotr(x: u32, n: u32) -> u32 {
    return (x >> n) | (x << (32u - n));
}

// SHA-digest — big-endian слова; targets хранятся как байты digest, упакованные
// в u32 little-endian. Для сравнения разворачиваем слово.
fn swap32(x: u32) -> u32 {
    return ((x & 0xFFu) << 24u) | ((x & 0xFF00u) << 8u) | ((x >> 8u) & 0xFF00u) | ((x >> 24u) & 0xFFu);
}

// SHA256 одного блока (кандидат <= 55 байт). Возвращает digest (32 байта = 8 слов).
fn sha256_block(candidate: array<u32, 16>) -> array<u32, 8> {
    var msg: array<u32, 16> = array<u32, 16>(
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u
    );
    let byte_len = params.mask_len;
    for (var j: u32 = 0u; j < byte_len; j = j + 1u) {
        let b = (candidate[j / 4u] >> ((j % 4u) * 8u)) & 0xFFu;
        msg[j / 4u] = msg[j / 4u] | (b << (8u * (3u - j % 4u)));
    }
    msg[byte_len / 4u] = msg[byte_len / 4u] | (0x80u << (8u * (3u - byte_len % 4u)));
    msg[15u] = byte_len * 8u;

    var h: array<u32, 8> = array<u32, 8>(
        0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
        0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u
    );

    var w: array<u32, 64> = array<u32, 64>(
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u,
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u,
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u,
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u
    );
    for (var i: u32 = 0u; i < 16u; i = i + 1u) {
        w[i] = msg[i];
    }
    for (var i: u32 = 16u; i < 64u; i = i + 1u) {
        let s0 = rotr(w[i - 15u], 7u) ^ rotr(w[i - 15u], 18u) ^ (w[i - 15u] >> 3u);
        let s1 = rotr(w[i - 2u], 17u) ^ rotr(w[i - 2u], 19u) ^ (w[i - 2u] >> 10u);
        w[i] = w[i - 16u] + s0 + w[i - 7u] + s1;
    }

    var a = h[0];
    var b = h[1];
    var c = h[2];
    var d = h[3];
    var e = h[4];
    var f = h[5];
    var g = h[6];
    var hh = h[7];

    for (var i: u32 = 0u; i < 64u; i = i + 1u) {
        let s1 = rotr(e, 6u) ^ rotr(e, 11u) ^ rotr(e, 25u);
        let ch = (e & f) ^ ((~e) & g);
        let temp1 = hh + s1 + ch + K[i] + w[i];
        let s0 = rotr(a, 2u) ^ rotr(a, 13u) ^ rotr(a, 22u);
        let maj = (a & b) ^ (a & c) ^ (b & c);
        let temp2 = s0 + maj;
        hh = g;
        g = f;
        f = e;
        e = d + temp1;
        d = c;
        c = b;
        b = a;
        a = temp1 + temp2;
    }

    var out: array<u32, 8> = array<u32, 8>(0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u);
    out[0] = a + h[0];
    out[1] = b + h[1];
    out[2] = c + h[2];
    out[3] = d + h[3];
    out[4] = e + h[4];
    out[5] = f + h[5];
    out[6] = g + h[6];
    out[7] = hh + h[7];
    return out;
}

@compute @workgroup_size(256)
fn main(@builtin(global_invocation_id) gid: vec3u) {
    let lid: u32 = gid.x;
    if (lid >= params.batch_len) {
        return;
    }
    let idx: u64 = params.batch_start + u64(lid);

    var candidate: array<u32, 16> = array<u32, 16>(
        0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u, 0u
    );
    var x: u64 = idx;
    for (var p: u32 = 0u; p < params.mask_len; p = p + 1u) {
        let pos = params.mask_len - 1u - p;
        let len: u64 = u64(charset_lens[pos]);
        let c: u32 = u32(x % len);
        x = x / len;
        let byte = charset[charset_starts[pos] + c];
        let word = pos / 4u;
        let shift = (pos % 4u) * 8u;
        candidate[word] = candidate[word] | (byte << shift);
    }

    let d = sha256_block(candidate);

    for (var t: u32 = 0u; t < params.num_targets; t = t + 1u) {
        let base = t * params.digest_words;
        var match_all = true;
        for (var w: u32 = 0u; w < params.digest_words; w = w + 1u) {
            if (swap32(d[w]) != targets[base + w]) {
                match_all = false;
                break;
            }
        }
        if (match_all) {
            let slot = atomicAdd(&results[0u], 1u);
            if (slot + 1u < RESULTS_CAPACITY) {
                atomicStore(&results[1u + slot * 2u], u32(idx));
                atomicStore(&results[2u + slot * 2u], u32(idx >> 32u));
            }
            return;
        }
    }
}
